"use client";
import { useState, useMemo } from "react";
import { useLanguage } from "@/lib/LanguageContext";
import { useTheme } from "next-themes";

// Simple markdown parser
function parseMarkdown(md: string): string {
    let html = md;

    // Headers
    html = html.replace(/^### (.*$)/gm, '<h3 class="text-lg font-semibold my-2">$1</h3>');
    html = html.replace(/^## (.*$)/gm, '<h2 class="text-xl font-semibold my-3">$1</h2>');
    html = html.replace(/^# (.*$)/gm, '<h1 class="text-2xl font-bold my-4">$1</h1>');

    // Bold and Italic
    html = html.replace(/\*\*\*(.*?)\*\*\*/g, '<strong><em>$1</em></strong>');
    html = html.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>');
    html = html.replace(/\*(.*?)\*/g, '<em>$1</em>');
    html = html.replace(/~~(.*?)~~/g, '<del>$1</del>');

    // Code blocks
    html = html.replace(/```([\s\S]*?)```/g, '<pre class="bg-gray-800 text-green-400 p-3 rounded-lg my-2 overflow-x-auto"><code>$1</code></pre>');
    html = html.replace(/`(.*?)`/g, '<code class="bg-gray-700 text-pink-400 px-1 rounded">$1</code>');

    // Links
    html = html.replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2" class="text-blue-400 underline" target="_blank" rel="noopener">$1</a>');

    // Images
    html = html.replace(/!\[([^\]]*)\]\(([^)]+)\)/g, '<img src="$2" alt="$1" class="max-w-full my-2 rounded" />');

    // Lists
    html = html.replace(/^\* (.*$)/gm, '<li class="ml-4">• $1</li>');
    html = html.replace(/^- (.*$)/gm, '<li class="ml-4">• $1</li>');
    html = html.replace(/^\d+\. (.*$)/gm, '<li class="ml-4 list-decimal">$1</li>');

    // Blockquotes
    html = html.replace(/^> (.*$)/gm, '<blockquote class="border-l-4 border-blue-500 pl-4 my-2 italic opacity-80">$1</blockquote>');

    // Horizontal rule
    html = html.replace(/^---$/gm, '<hr class="my-4 border-gray-600" />');

    // Line breaks
    html = html.replace(/\n\n/g, '</p><p class="my-2">');
    html = html.replace(/\n/g, '<br />');

    return `<p class="my-2">${html}</p>`;
}

export default function MarkdownPreviewTool() {
    const [input, setInput] = useState(`# Hello World

This is a **Markdown** preview tool.

## Features
- Live preview
- GitHub flavored markdown
- Code highlighting

\`\`\`javascript
const hello = "world";
console.log(hello);
\`\`\`

> This is a blockquote

[Visit DevLab](https://devlab.com)
`);
    const [copied, setCopied] = useState(false);
    const { t } = useLanguage();
    const { theme } = useTheme();

    const preview = useMemo(() => parseMarkdown(input), [input]);

    const handleCopyHtml = () => {
        navigator.clipboard.writeText(preview);
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
    };

    return (
        <div className={`relative w-full p-8 rounded-2xl max-w-7xl mx-auto shadow-xl
      backdrop-blur-md border
      ${theme === "dark"
                ? "bg-transparent border-[rgba(255,255,255,0.07)]"
                : "bg-white/80 border-gray-200"}`}>

            <h2 className={`text-xl font-semibold mb-4 ${theme === "dark" ? "text-white" : "text-slate-800"}`}>
                {t("tools.markdown.title")}
            </h2>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {/* Editor */}
                <div>
                    <div className={`text-sm font-medium mb-2 ${theme === "dark" ? "text-slate-300" : "text-slate-600"}`}>
                        {t("tools.markdown.editor")}
                    </div>
                    <textarea
                        value={input}
                        onChange={(e) => setInput(e.target.value)}
                        placeholder={t("tools.markdown.placeholder")}
                        className={`w-full h-[750px] px-4 py-3 rounded-lg text-sm border outline-none focus:ring-1 ring-indigo-500 resize-none font-mono
              ${theme === "dark"
                                ? "bg-[#111] text-slate-200 border-slate-700"
                                : "bg-gray-50 text-slate-800 border-gray-300"}`}
                    />
                </div>

                {/* Preview */}
                <div>
                    <div className="flex justify-between items-center mb-2">
                        <span className={`text-sm font-medium ${theme === "dark" ? "text-slate-300" : "text-slate-600"}`}>
                            {t("tools.markdown.preview")}
                        </span>
                        <button
                            onClick={handleCopyHtml}
                            className={`text-xs px-3 py-1 rounded-lg transition
                ${copied
                                    ? "bg-green-500 text-white"
                                    : theme === "dark" ? "bg-slate-700 text-slate-300" : "bg-gray-200 text-slate-700"}`}
                        >
                            {copied ? t("tools.common.copied") : t("tools.markdown.copyHtml")}
                        </button>
                    </div>
                    <div
                        className={`w-full h-[750px] p-4 rounded-lg text-sm overflow-y-auto
              ${theme === "dark"
                                ? "bg-[#0a0a0a] text-slate-200 border border-slate-700"
                                : "bg-gray-100 text-slate-800 border border-gray-300"}`}
                        dangerouslySetInnerHTML={{ __html: preview }}
                    />
                </div>
            </div>
        </div>
    );
}
